// ============================================================
// PrivacySettings.js — Configurações de Privacidade e Bloqueio
// Rota: /settings/privacy
// ============================================================
import React, { useState, useEffect, useContext } from 'react';
import { AuthContext } from '../context/AuthContext';
import '../styles/PrivacySettings.css';

const API = process.env.REACT_APP_API_URL || 'http://localhost:8787';

const PrivacySettings = () => {
  const { token } = useContext(AuthContext);

  const [settings, setSettings] = useState({
    privacy: 'public',
    show_online: true,
    allow_messages: 'everyone',
    show_activity: true,
  });

  const [blockedUsers, setBlockedUsers] = useState([]);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [message, setMessage] = useState({ type: '', text: '' });

  // Carrega configurações e lista de bloqueados
  useEffect(() => {
    const fetchData = async () => {
      try {
        const [privRes, blockRes] = await Promise.all([
          fetch(`${API}/api/users/privacy`, {
            headers: { Authorization: `Bearer ${token}` },
          }),
          fetch(`${API}/api/users/blocked`, {
            headers: { Authorization: `Bearer ${token}` },
          }),
        ]);

        if (privRes.ok) {
          const privData = await privRes.json();
          setSettings(privData);
        }

        if (blockRes.ok) {
          const blockData = await blockRes.json();
          setBlockedUsers(blockData.blocked || []);
        }
      } catch (err) {
        console.error('Erro ao carregar configurações:', err);
      } finally {
        setLoading(false);
      }
    };

    fetchData();
  }, [token]);

  const showMessage = (type, text) => {
    setMessage({ type, text });
    setTimeout(() => setMessage({ type: '', text: '' }), 3000);
  };

  // Salva configurações de privacidade
  const handleSave = async () => {
    setSaving(true);
    try {
      const res = await fetch(`${API}/api/users/privacy`, {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify(settings),
      });

      if (res.ok) {
        showMessage('success', '✅ Configurações salvas com sucesso!');
      } else {
        const data = await res.json();
        showMessage('error', `❌ ${data.error || 'Erro ao salvar.'}`);
      }
    } catch (err) {
      showMessage('error', '❌ Erro de conexão. Tente novamente.');
    } finally {
      setSaving(false);
    }
  };

  // Desbloquear usuário
  const handleUnblock = async (userId, username) => {
    if (!window.confirm(`Desbloquear @${username}?`)) return;

    try {
      const res = await fetch(`${API}/api/users/${userId}/block`, {
        method: 'DELETE',
        headers: { Authorization: `Bearer ${token}` },
      });

      if (res.ok) {
        setBlockedUsers(prev => prev.filter(u => u.id !== userId));
        showMessage('success', `✅ @${username} foi desbloqueado.`);
      } else {
        showMessage('error', '❌ Erro ao desbloquear.');
      }
    } catch (err) {
      showMessage('error', '❌ Erro de conexão.');
    }
  };

  if (loading) {
    return (
      <div className="privacy-page">
        <div className="privacy-loading">
          <div className="spinner-large" />
          <p>Carregando configurações...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="privacy-page">
      <div className="privacy-container">
        <h1 className="privacy-title">🔒 Privacidade e Segurança</h1>

        {message.text && (
          <div className={`privacy-alert ${message.type}`}>
            {message.text}
          </div>
        )}

        {/* ── Visibilidade do Perfil ── */}
        <section className="privacy-section">
          <h2 className="section-title">👤 Visibilidade do Perfil</h2>

          <div className="option-group">
            <label className="option-label">
              <div className="option-info">
                <span className="option-name">Perfil público</span>
                <span className="option-desc">Qualquer pessoa pode ver seu perfil e posts</span>
              </div>
              <div className="radio-group">
                <label className="radio-option">
                  <input
                    type="radio"
                    name="privacy"
                    value="public"
                    checked={settings.privacy === 'public'}
                    onChange={() => setSettings(s => ({ ...s, privacy: 'public' }))}
                  />
                  <span>Público</span>
                </label>
                <label className="radio-option">
                  <input
                    type="radio"
                    name="privacy"
                    value="private"
                    checked={settings.privacy === 'private'}
                    onChange={() => setSettings(s => ({ ...s, privacy: 'private' }))}
                  />
                  <span>Privado</span>
                </label>
              </div>
            </label>
          </div>

          {settings.privacy === 'private' && (
            <div className="privacy-notice">
              🔒 Perfil privado: apenas seus seguidores aprovados podem ver seus posts e informações.
            </div>
          )}
        </section>

        {/* ── Atividade e Presença ── */}
        <section className="privacy-section">
          <h2 className="section-title">🟢 Atividade e Presença</h2>

          <div className="toggle-item">
            <div className="toggle-info">
              <span className="toggle-name">Mostrar quando estou online</span>
              <span className="toggle-desc">Outros usuários verão o indicador verde no seu perfil</span>
            </div>
            <label className="toggle-switch">
              <input
                type="checkbox"
                checked={settings.show_online}
                onChange={(e) => setSettings(s => ({ ...s, show_online: e.target.checked }))}
              />
              <span className="toggle-slider" />
            </label>
          </div>

          <div className="toggle-item">
            <div className="toggle-info">
              <span className="toggle-name">Mostrar atividade recente</span>
              <span className="toggle-desc">Exibir "visto por último" e atividade no perfil</span>
            </div>
            <label className="toggle-switch">
              <input
                type="checkbox"
                checked={settings.show_activity}
                onChange={(e) => setSettings(s => ({ ...s, show_activity: e.target.checked }))}
              />
              <span className="toggle-slider" />
            </label>
          </div>
        </section>

        {/* ── Mensagens ── */}
        <section className="privacy-section">
          <h2 className="section-title">💬 Quem pode me enviar mensagens</h2>

          <div className="select-group">
            {[
              { value: 'everyone', label: '🌍 Todos', desc: 'Qualquer usuário pode te enviar mensagem' },
              { value: 'followers', label: '👥 Apenas seguidores', desc: 'Somente quem você segue de volta' },
              { value: 'nobody', label: '🚫 Ninguém', desc: 'Desativar mensagens privadas' },
            ].map(opt => (
              <label key={opt.value} className={`select-option ${settings.allow_messages === opt.value ? 'selected' : ''}`}>
                <input
                  type="radio"
                  name="allow_messages"
                  value={opt.value}
                  checked={settings.allow_messages === opt.value}
                  onChange={() => setSettings(s => ({ ...s, allow_messages: opt.value }))}
                />
                <div>
                  <span className="select-label">{opt.label}</span>
                  <span className="select-desc">{opt.desc}</span>
                </div>
              </label>
            ))}
          </div>
        </section>

        {/* Botão salvar */}
        <button
          className="btn-save"
          onClick={handleSave}
          disabled={saving}
        >
          {saving ? '⏳ Salvando...' : '💾 Salvar configurações'}
        </button>

        {/* ── Usuários Bloqueados ── */}
        <section className="privacy-section blocked-section">
          <h2 className="section-title">🚫 Usuários Bloqueados ({blockedUsers.length})</h2>

          {blockedUsers.length === 0 ? (
            <div className="empty-blocked">
              <span>✅</span>
              <p>Você não bloqueou nenhum usuário.</p>
            </div>
          ) : (
            <div className="blocked-list">
              {blockedUsers.map(user => (
                <div key={user.id} className="blocked-item">
                  <div className="blocked-user-info">
                    <div className="blocked-avatar">
                      {user.avatar_url ? (
                        <img src={user.avatar_url} alt={user.display_name} />
                      ) : (
                        <span>{user.display_name?.[0]?.toUpperCase() || '?'}</span>
                      )}
                    </div>
                    <div>
                      <p className="blocked-name">{user.display_name}</p>
                      <p className="blocked-username">@{user.username}</p>
                    </div>
                  </div>
                  <button
                    className="btn-unblock"
                    onClick={() => handleUnblock(user.id, user.username)}
                  >
                    Desbloquear
                  </button>
                </div>
              ))}
            </div>
          )}
        </section>
      </div>
    </div>
  );
};

export default PrivacySettings;
